CREATE TABLE life_festival_plans(id INTEGER PRIMARY KEY,title TEXT NOT NULL,year INTEGER NOT NULL,start_on TEXT NOT NULL,end_on TEXT NOT NULL,budget REAL NOT NULL DEFAULT 0 CHECK(budget>=0),notes TEXT NOT NULL DEFAULT '',CHECK(start_on<=end_on));
CREATE TABLE life_festival_items(id INTEGER PRIMARY KEY,plan_id INTEGER NOT NULL REFERENCES life_festival_plans(id) ON DELETE CASCADE,title TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'task',amount REAL NOT NULL DEFAULT 0 CHECK(amount>=0),done INTEGER NOT NULL DEFAULT 0 CHECK(done IN (0,1)));
CREATE TABLE life_seettu(id INTEGER PRIMARY KEY,name TEXT NOT NULL,contribution REAL NOT NULL CHECK(contribution>0),frequency TEXT NOT NULL CHECK(frequency IN ('weekly','monthly')),rounds INTEGER NOT NULL CHECK(rounds BETWEEN 1 AND 120),start_on TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_seettu_payments(id INTEGER PRIMARY KEY,seettu_id INTEGER NOT NULL REFERENCES life_seettu(id) ON DELETE CASCADE,round_no INTEGER NOT NULL,paid_on TEXT NOT NULL,amount REAL NOT NULL CHECK(amount>0),status TEXT NOT NULL DEFAULT 'paid' CHECK(status IN ('paid','missed')),UNIQUE(seettu_id,round_no));
CREATE TABLE life_utilities(id INTEGER PRIMARY KEY,provider TEXT NOT NULL,account_ref TEXT NOT NULL DEFAULT '',frequency TEXT NOT NULL CHECK(frequency IN ('monthly','quarterly','other')),due_day INTEGER CHECK(due_day BETWEEN 1 AND 31),notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_utility_readings(id INTEGER PRIMARY KEY,utility_id INTEGER NOT NULL REFERENCES life_utilities(id) ON DELETE CASCADE,reading_on TEXT NOT NULL,usage REAL,amount REAL NOT NULL CHECK(amount>=0),notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_vehicles(id INTEGER PRIMARY KEY,name TEXT NOT NULL,registration TEXT NOT NULL DEFAULT '',make_model TEXT NOT NULL DEFAULT '',insurance_expiry TEXT,licence_expiry TEXT,emission_expiry TEXT,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_vehicle_services(id INTEGER PRIMARY KEY,vehicle_id INTEGER NOT NULL REFERENCES life_vehicles(id) ON DELETE CASCADE,service_on TEXT NOT NULL,odometer INTEGER,cost REAL NOT NULL DEFAULT 0 CHECK(cost>=0),notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_metals(id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('gold','jewellery','other')),weight REAL NOT NULL CHECK(weight>0),unit TEXT NOT NULL DEFAULT 'g',purity REAL,acquired_on TEXT NOT NULL,cost REAL NOT NULL DEFAULT 0 CHECK(cost>=0),notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_metal_prices(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,price_per_unit REAL NOT NULL CHECK(price_per_unit>0),unit TEXT NOT NULL DEFAULT 'g',priced_on TEXT NOT NULL,source TEXT NOT NULL DEFAULT '');
CREATE TABLE life_deposits(id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('fixed_deposit','t_bill','other')),principal REAL NOT NULL CHECK(principal>0),rate REAL NOT NULL DEFAULT 0 CHECK(rate>=0),rate_type TEXT NOT NULL DEFAULT 'annual' CHECK(rate_type IN ('annual','flat')),start_on TEXT NOT NULL,maturity_on TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_fx_rates(id INTEGER PRIMARY KEY,code TEXT NOT NULL,rate_lkr REAL NOT NULL CHECK(rate_lkr>0),as_of TEXT NOT NULL,source TEXT NOT NULL DEFAULT '',UNIQUE(code,as_of));
CREATE TABLE life_events(id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'event',event_on TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_event_contributions(id INTEGER PRIMARY KEY,event_id INTEGER NOT NULL REFERENCES life_events(id) ON DELETE CASCADE,person TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN ('given','received')),amount REAL NOT NULL CHECK(amount>0),paid_on TEXT,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_health_logs(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,logged_on TEXT NOT NULL,value REAL,unit TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_health_reminders(id INTEGER PRIMARY KEY,title TEXT NOT NULL,kind TEXT NOT NULL,next_on TEXT NOT NULL,frequency TEXT NOT NULL DEFAULT 'once',notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','done')));
CREATE TABLE life_meals(id INTEGER PRIMARY KEY,meal_date TEXT NOT NULL,slot TEXT NOT NULL,title TEXT NOT NULL,servings INTEGER NOT NULL DEFAULT 1 CHECK(servings>0),notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_groceries(id INTEGER PRIMARY KEY,item TEXT NOT NULL,quantity REAL NOT NULL DEFAULT 1,unit TEXT NOT NULL DEFAULT '',estimated_cost REAL NOT NULL DEFAULT 0 CHECK(estimated_cost>=0),bought INTEGER NOT NULL DEFAULT 0 CHECK(bought IN (0,1)),needed_on TEXT);
CREATE TABLE life_wishlist(id INTEGER PRIMARY KEY,title TEXT NOT NULL,amount REAL NOT NULL DEFAULT 0 CHECK(amount>=0),added_on TEXT NOT NULL,revisit_on TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','bought','dropped')),notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_contacts(id INTEGER PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',birthday TEXT,next_followup TEXT,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE life_followups(id INTEGER PRIMARY KEY,contact_id INTEGER NOT NULL REFERENCES life_contacts(id) ON DELETE CASCADE,due_on TEXT NOT NULL,note TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','done')));
CREATE INDEX life_health_due ON life_health_reminders(status,next_on);
CREATE INDEX life_wishlist_due ON life_wishlist(status,revisit_on);
CREATE INDEX life_followup_due ON life_followups(status,due_on);
